// 89
function prime_fib(n){
    function isPrime(number){
        if(number <= 3){
            return number > 1;
        }

fim_suffix:
            return false;
        }
        else{
            for(var i = 5; i * i <= number; i += 6){
                if(number % i == 0 || number % (i + 2) == 0){
                    return false;
                }
            }
            return true;
        }
    }
    function fib(num){
        var a = 1, b = 0, temp;

        while (num >= 0){
            temp = a;
            a = a + b;
            b = temp;
            num--;
        }

        return b;
    }
