        if (c == -1) {
            throw new EOFException();
        }
        return c;
    }

    /**
     * Read a 32-bit integer from the stream.
     */
    private int readInt32()
        throws IOException
    {
        return read() + 256 * read() + 65536 * read() + 16777216 * read();
