    public static Set<OWLGraphEdge> findCommonSubsumersAsEdges(OWLGraphWrapper g, OWLObject x, OWLObject y) {
        Set<OWLGraphEdge> xs = g.getOutgoingEdgesClosure(x);
        Set<OWLGraphEdge> ys = g.getOutgoingEdgesClosure(y);
        xs.retainAll(ys);
