        Set<OWLGraphEdge> cses = findCommonSubsumersAsEdges(g, x, y);
        Set<OWLGraphEdge> lcses = new HashSet<OWLGraphEdge>();
        lcses.addAll(cses);
        for (OWLGraphEdge cse : cses) {
            Set<OWLObject> zs = g.getAncestors(cse.getSource());
