    {
        if (o == null) {
            write(Operations.NONE);
        }
        else if (myMemo.containsKey(o)) {
            get(o);
        }
        else if (o instanceof Boolean) {
            write(((Boolean) o) ? Operations.NEWTRUE : Operations.NEWFALSE);
