     *            set to true, it's up to the valueFunction to only use the duration events that is
     *            actually included in the window.
     * @return min/max window value and range
     */
    public static Pair<IQuantity, IRange<IQuantity>> slidingWindowUnorderedMinMaxValue(IItemCollection items, IQuantity windowSize, final FutureTask<IResult> cancellationSupplier, final IUnorderedWindowValueFunction<IQuantity> valueFunction, boolean max, boolean includeIntersecting) {
        IQuantity slideSize = windowSize.getUnit().quantity(windowSize.ratioTo(windowSize.getUnit().quantity(2)));
        return slidingWindowUnorderedMinMaxValue(items, windowSize, slideSize, cancellationSupplier, valueFunction, max, includeIntersecting);
