        return slidingWindowUnorderedMinMaxValue(items, windowSize, slideSize, cancellationSupplier, valueFunction, QUANTITY_COMPARATOR, max, includeIntersecting);
    }

    private static final Comparator<IQuantity> QUANTITY_COMPARATOR = new Comparator<IQuantity>() {

        @Override
