    public static <V> Pair<V, IRange<IQuantity>> slidingWindowUnorderedMinMaxValue(IItemCollection items, IQuantity windowSize, final FutureTask<IResult> cancellationSupplier, final IUnorderedWindowValueFunction<V> valueFunction, final Comparator<V> valueComparator, boolean max, boolean includeIntersecting)

