        self,
        image: torch.Tensor,
        model: GFPGANer,
        aligned=False,
        only_center_face=False,
        weight=0.5,
        save_tmp_steps=True,
    ) -> Tuple[torch.Tensor]:
        out = [
            self.do_restore(
                image[i], model, aligned, only_center_face, weight, save_tmp_steps
            )
            for i in range(image.size(0))
        ]

