  public String buildRequest(List<PackageRef> packages) throws JsonProcessingException {
    ArrayNode coordinates = mapper.createArrayNode();
    packages.stream()
        .map(PackageRef::purl)
        .filter(Objects::nonNull)
        .forEach(purl -> coordinates.add(purl.getCoordinates()));

